        }
        if (0xD800..=0xDFFF).contains(&cp) {
            return Err(Utf8Error::IllFormed { position: i });
        }
        if cp > 0x10FFFF {
            return Err(Utf8Error::IllFormed { position: i });
        }
        i += len;
    }
    Ok(())
